namespace eval left {oo::class create C {}}
namespace eval right {oo::class create C {}}
oo::class create C {}
namespace eval app {
    namespace path {::left ::right}
    set one [C new]
    puts [info object class $one]
    namespace path {::right ::left}
    set two [C new]
    puts [info object class $two]
    proc C {args} {return LOCAL}
    puts [C new]
}
